## Method and reasoning
First root at node 1, compute the sum of depths and accumulate subtree sizes in reverse order. Moving the root across an edge into child v shifts size[v] distances down by one and the other n−size[v] distances up by one. Thus answer[v]=answer[parent]+n−2·size[v]. Use 64-bit totals and iterative traversals.

## Walk through the sample
From vertex 1 the distance sum is 5. Crossing to 2 moves three vertices one step closer and one vertex farther, giving 5 − 3 + 1 = 3. Crossing from 2 to the leaf 3 reverses those counts and gives 5.

## Complexity
Time and space O(n).

## Reference implementation
~~~
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<int>> g(n + 1);
    for (int i = 1; i < n; ++i) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    vector<int> parent(n + 1), depth(n + 1), size(n + 1, 1), order{1};
    vector<long long> answer(n + 1);
    for (size_t i = 0; i < order.size(); ++i) {
        int v = order[i];
        answer[1] += depth[v];
        for (int u : g[v])
            if (u != parent[v]) {
                parent[u] = v;
                depth[u] = depth[v] + 1;
                order.push_back(u);
            }
    }
    for (int i = n - 1; i > 0; --i)
        size[parent[order[i]]] += size[order[i]];
    for (int i = 1; i < n; ++i) {
        int v = order[i];
        answer[v] = answer[parent[v]] + n - 2LL * size[v];
    }
    for (int i = 1; i <= n; ++i)
        cout << answer[i] << (i == n ? '\n' : ' ');
}
~~~
